(2006016, 276389, 44601, '<td valign="top">Too blur, too dark, can''t see.</td>', 'Too blur, too dark, can''t see.', '2006-01-05 05:27:27.000000', NULL, 1),
(2006021, 276247, 33363, '<td valign="top">This is pretty cool, but I feel like if I could see part of the ground or something in it, I would get a better feeling of perspective and not feel as if I''m looking from half-way up the towers.</td>', 'This is pretty cool, but I feel like if I could see part of the ground or something in it, I would get a better feeling of perspective and not feel as if I''m looking from half-way up the towers.', '2006-01-05 05:35:41.000000', NULL, 1),
(2006023, 276076, 33363, '<td valign="top">Nice motion blur - I feel like it might lend a lot to this photo if one of the people were still and in focus.</td>', 'Nice motion blur - I feel like it might lend a lot to this photo if one of the people were still and in focus.', '2006-01-05 05:37:40.000000', NULL, 1),
(2006025, 276348, 33363, '<td valign="top">Nice angle, but the light is a bit "dull" which I feel detracts from the picture a bit.</td>', 'Nice angle, but the light is a bit "dull" which I feel detracts from the picture a bit.', '2006-01-05 05:39:52.000000', NULL, 1),
(2006027, 276099, 33363, '<td valign="top">Definately seeing the crowds here, but I feel like you could have made me feel more "part of" the bustle by getting in closer.</td>', 'Definately seeing the crowds here, but I feel like you could have made me feel more "part of" the bustle by getting in closer.', '2006-01-05 05:42:26.000000', NULL, 1),
(2006028, 276268, 33363, '<td valign="top">What a sky! I really like this :)</td>', 'What a sky! I really like this :)', '2006-01-05 05:43:02.000000', NULL, 1),
(2006030, 276164, 33363, '<td valign="top">I feel like if you''d taken this from a lower angle, it might help me feel the grittiness of the street and down town.</td>', 'I feel like if you''d taken this from a lower angle, it might help me feel the grittiness of the street and down town.', '2006-01-05 05:45:08.000000', NULL, 1),
(2006039, 273455, 50251, '<td valign="top">I like the idea of photographing the old time to tandem with the word "Times"</td>', 'I like the idea of photographing the old time to tandem with the word "Times"', '2006-01-05 05:52:37.000000', NULL, 1),
(2006052, 276116, 31443, '<td valign="top">Sometimes a photo says a 1000 words, this one does. Grandpa looking out and protecting his young grandchildren..I like this image very much</td>', 'Sometimes a photo says a 1000 words, this one does. Grandpa looking out and protecting his young grandchildren..I like this image very much', '2006-01-05 06:01:56.000000', NULL, 1);
