(2007200, 276303, 37961, '<td valign="top">Wow. What a punch of color. Nice.</td>', 'Wow. What a punch of color. Nice.', '2006-01-05 14:03:16.000000', NULL, 1),
(2007208, 276267, 16950, '<td valign="top">10 from me.  Great photo!  The only thing I might have change was to crop a little less of the top off, so you can see the whole train.</td>', '10 from me.  Great photo!  The only thing I might have change was to crop a little less of the top off, so you can see the whole train.', '2006-01-05 14:06:16.000000', NULL, 1),
(2007214, 274853, 15574, '<td valign="top">What''s up with the purple tint?</td>', 'What''s up with the purple tint?', '2006-01-05 14:08:34.000000', NULL, 1),
(2007217, 275950, 16950, '<td valign="top">This picture is highly pixilated, which will unfortunately bring low scores.  Try using more pixles if possible (not sure if this was cropped out from a larger picture).  There is also a good tutorial here for resizing pictures for the web that may also help.</td>', 'This picture is highly pixilated, which will unfortunately bring low scores.  Try using more pixles if possible (not sure if this was cropped out from a larger picture).  There is also a good tutorial here for resizing pictures for the web that may also help.', '2006-01-05 14:09:54.000000', NULL, 1),
(2007218, 276472, 16950, '<td valign="top">Try to get the long side of your photo as close to 640 pixels as you can.  You will lose points for submitting such a small picture because it is hard to see any detail..</td>', 'Try to get the long side of your photo as close to 640 pixels as you can.  You will lose points for submitting such a small picture because it is hard to see any detail..', '2006-01-05 14:11:06.000000', NULL, 1),
(2007221, 275767, 16950, '<td valign="top">I came back to this picture several times.  Somthing in it just grabs my attention.  Bumping up, 9.</td>', 'I came back to this picture several times.  Somthing in it just grabs my attention.  Bumping up, 9.', '2006-01-05 14:12:31.000000', NULL, 1),
