(2010029, 276367, 50502, '<td valign="top">Really like the clarity and perspective and choice of B+W, seems a little cluttered though</td>', 'Really like the clarity and perspective and choice of B+W, seems a little cluttered though', '2006-01-06 13:53:32.000000', NULL, 1),
(2010031, 274402, 50502, '<td valign="top">Nice portrait of musician and DOF that comparatively blurs the BG figures; trees seem to block it in and limit the perspective on the city though</td>', 'Nice portrait of musician and DOF that comparatively blurs the BG figures; trees seem to block it in and limit the perspective on the city though', '2006-01-06 13:54:57.000000', NULL, 1),
(2010033, 276058, 50502, '<td valign="top">Beautiful colors on fireworks; building itself seems a bit unfocused and dark figures in FG vague, plus not so much of the ''city'' here</td>', 'Beautiful colors on fireworks; building itself seems a bit unfocused and dark figures in FG vague, plus not so much of the ''city'' here', '2006-01-06 13:56:33.000000', NULL, 1),
(2010035, 275940, 50502, '<td valign="top">Seems a bit confused and not so well defined</td>', 'Seems a bit confused and not so well defined', '2006-01-06 13:56:58.000000', NULL, 1),
(2010036, 276319, 50502, '<td valign="top">Beautiful coloration and perspective here, contrast between sky and traffic stream; the only thing I wished for was more clarity and definition in the BG which occupies half of the picture</td>', 'Beautiful coloration and perspective here, contrast between sky and traffic stream; the only thing I wished for was more clarity and definition in the BG which occupies half of the picture', '2006-01-06 13:58:30.000000', NULL, 1),
(2010037, 273403, 38234, '<td valign="top">I really like this shot but I can''t see how it depicts City Life:-( as I think it could have been easily shot in a country church/house where ever</td>', 'I really like this shot but I can''t see how it depicts City Life:-( as I think it could have been easily shot in a country church/house where ever', '2006-01-06 13:58:40.000000', NULL, 1),
(2010040, 274158, 50502, '<td valign="top">Dont'' care too much for the excessive blurring here, no point of sharpness in the photograph</td>', 'Dont'' care too much for the excessive blurring here, no point of sharpness in the photograph', '2006-01-06 13:59:08.000000', NULL, 1),
(2010041, 274862, 50502, '<td valign="top">Interesting portrait, would like to be closer in and reveal more of subject''s face; plus environment doesn''t reveal very much city here</td>', 'Interesting portrait, would like to be closer in and reveal more of subject''s face; plus environment doesn''t reveal very much city here', '2006-01-06 14:00:14.000000', NULL, 1),
(2010043, 275018, 50502, '<td valign="top">Very interesting perspective but seems overexposed and not sure I care for the blurred effect</td>', 'Very interesting perspective but seems overexposed and not sure I care for the blurred effect', '2006-01-06 14:01:22.000000', NULL, 1),
(2010047, 274602, 50502, '<td valign="top">A figure of great pathos, nicely captured</td>', 'A figure of great pathos, nicely captured', '2006-01-06 14:02:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2010050, 275334, 50502, '<td valign="top">Interesting arrangement of these pipes, would like to see more ''city'' here in the surrounding environment</td>', 'Interesting arrangement of these pipes, would like to see more ''city'' here in the surrounding environment', '2006-01-06 14:02:49.000000', NULL, 1),
(2010053, 276363, 50502, '<td valign="top">Interesting effect on lights, but they seem a bit unfocused</td>', 'Interesting effect on lights, but they seem a bit unfocused', '2006-01-06 14:03:53.000000', NULL, 1),
(2010060, 276448, 50502, '<td valign="top">Nice capture of the moment and nice perspective; maybe white balance could be less brown, figures also slightly dark</td>', 'Nice capture of the moment and nice perspective; maybe white balance could be less brown, figures also slightly dark', '2006-01-06 14:05:05.000000', NULL, 1),
(2010064, 274755, 50502, '<td valign="top">Interesting perspective and color; wide angle makes objects seem diminished in size though and too much blank whiteness in top section</td>', 'Interesting perspective and color; wide angle makes objects seem diminished in size though and too much blank whiteness in top section', '2006-01-06 14:05:58.000000', NULL, 1),
(2010070, 275036, 50502, '<td valign="top">Interesting but a little confined in perspective; seems also to cry out for the addition of people in the picture</td>', 'Interesting but a little confined in perspective; seems also to cry out for the addition of people in the picture', '2006-01-06 14:09:22.000000', NULL, 1),
(2010073, 275395, 50502, '<td valign="top">Really liked colors on left and right but center of photo not so interesting, not much visible in center background</td>', 'Really liked colors on left and right but center of photo not so interesting, not much visible in center background', '2006-01-06 14:10:29.000000', NULL, 1),
(2010094, 274374, 44743, '<td valign="top">It''s a fun picture.  My biggest concern is that it''s not terribly original: The  sign was designed to take this very shot, making it seem less creative.</td>', 'It''s a fun picture.  My biggest concern is that it''s not terribly original: The  sign was designed to take this very shot, making it seem less creative.', '2006-01-06 14:22:09.000000', NULL, 1),
(2010096, 273403, 42968, '<td valign="top">Great Pic. Beautiful girl (I have 3) But my opinion, does not fall into the City theme. In another theme I would give the photo a 10</td>', 'Great Pic. Beautiful girl (I have 3) But my opinion, does not fall into the City theme. In another theme I would give the photo a 10', '2006-01-06 14:22:55.000000', NULL, 1),
(2010098, 274853, 44743, '<td valign="top">"City" theme is definitely there, but the shot seems slightly fuzzy?</td>', '"City" theme is definitely there, but the shot seems slightly fuzzy?', '2006-01-06 14:23:22.000000', NULL, 1),
(2010100, 275948, 44743, '<td valign="top">That is a great job on the reflection.  Very crisp.</td>', 'That is a great job on the reflection.  Very crisp.', '2006-01-06 14:23:58.000000', NULL, 1),
(2010101, 276215, 49672, '<td valign="top">Good, but a bit too much camera shake.</td>', 'Good, but a bit too much camera shake.', '2006-01-06 14:24:19.000000', NULL, 1),
(2010102, 276067, 49672, '<td valign="top">OMG - Get me out of there!</td>', 'OMG - Get me out of there!', '2006-01-06 14:24:39.000000', NULL, 1),
(2010104, 275242, 44743, '<td valign="top">Nicely done.  Powerful image.  The figure watching the smoke adds a lot.</td>', 'Nicely done.  Powerful image.  The figure watching the smoke adds a lot.', '2006-01-06 14:24:56.000000', NULL, 1),
(2010107, 276058, 31443, '<td valign="top">Very special moment, great shot, too bad about basic editing, the lampost on the left is a terrible eyesore..</td>', 'Very special moment, great shot, too bad about basic editing, the lampost on the left is a terrible eyesore..', '2006-01-06 14:26:00.000000', NULL, 1),
(2010108, 274114, 44743, '<td valign="top">It looks like a nice shot of the water, but it needs to be bigger so that we can see the detail.</td>', 'It looks like a nice shot of the water, but it needs to be bigger so that we can see the detail.', '2006-01-06 14:26:14.000000', NULL, 1),
(2010109, 276113, 31443, '<td valign="top">Simply beautiful!</td>', 'Simply beautiful!', '2006-01-06 14:26:19.000000', NULL, 1),
(2010113, 274658, 44743, '<td valign="top">Nice, crisp shot of the city w/a great title.</td>', 'Nice, crisp shot of the city w/a great title.', '2006-01-06 14:27:06.000000', NULL, 1),
(2010115, 276316, 44743, '<td valign="top">I was hoping to see a lot of "gritty" faces like this in the City challenge.  Nice!</td>', 'I was hoping to see a lot of "gritty" faces like this in the City challenge.  Nice!', '2006-01-06 14:27:48.000000', NULL, 1),
(2010123, 275328, 44743, '<td valign="top">The colors are nice.  I think the shot would do a bit better if it were straighter &amp; a bit less grainy.</td>', 'The colors are nice.  I think the shot would do a bit better if it were straighter & a bit less grainy.', '2006-01-06 14:29:45.000000', NULL, 1),
(2010127, 274606, 44743, '<td valign="top">Excellent lighting!</td>', 'Excellent lighting!', '2006-01-06 14:30:18.000000', NULL, 1),
(2010131, 276098, 44743, '<td valign="top">Great DOF, nice lighting, and good title.</td>', 'Great DOF, nice lighting, and good title.', '2006-01-06 14:30:54.000000', NULL, 1),
(2010135, 273455, 44743, '<td valign="top">Great title.  Love his expression.  Nice shot.</td>', 'Great title.  Love his expression.  Nice shot.', '2006-01-06 14:31:44.000000', NULL, 1),
(2010141, 276116, 44743, '<td valign="top">I like this one a lot.  Nice capture of the expressions.  Great crop.</td>', 'I like this one a lot.  Nice capture of the expressions.  Great crop.', '2006-01-06 14:33:37.000000', NULL, 1),
(2010147, 274721, 50641, '<td valign="top">Nice catch, great expression.  Makes me thirsty.</td>', 'Nice catch, great expression.  Makes me thirsty.', '2006-01-06 14:35:15.000000', NULL, 1),
(2010157, 275933, 44743, '<td valign="top">Very nice job to make the surrounding people seem ghostlike.  The long shutter gives a nice tranquil look to the water, too.  My only (minor) concern is that the saturated lights look a bit harsh.</td>', 'Very nice job to make the surrounding people seem ghostlike.  The long shutter gives a nice tranquil look to the water, too.  My only (minor) concern is that the saturated lights look a bit harsh.', '2006-01-06 14:37:50.000000', NULL, 1),
(2010160, 275339, 50641, '<td valign="top">Great title.  Good eye for the microcosmic story.  I can''t decide whether the stuff to the left distracts me or fills out the shot.  Love the bent broom handle and the VW butt.  Thanks.</td>', 'Great title.  Good eye for the microcosmic story.  I can''t decide whether the stuff to the left distracts me or fills out the shot.  Love the bent broom handle and the VW butt.  Thanks.', '2006-01-06 14:39:06.000000', NULL, 1),
(2010161, 276360, 50780, '<td valign="top">I like the comparison of the city lights against the Christmas lights. Good exposure of both, which is sometimes difficult to do.</td>', 'I like the comparison of the city lights against the Christmas lights. Good exposure of both, which is sometimes difficult to do.', '2006-01-06 14:39:11.000000', NULL, 1),
(2010164, 273567, 50780, '<td valign="top">I like your use of colour, especially in contrast to the washed out grey-brown of the smog.</td>', 'I like your use of colour, especially in contrast to the washed out grey-brown of the smog.', '2006-01-06 14:40:53.000000', NULL, 1),
(2010165, 276140, 44743, '<td valign="top">Great / clever title.  The only problem is that the pixels look very noisy-- perhaps you had to crop too much to ''zoom'' in on the bird?</td>', 'Great / clever title.  The only problem is that the pixels look very noisy-- perhaps you had to crop too much to ''zoom'' in on the bird?', '2006-01-06 14:41:08.000000', NULL, 1),
(2010169, 275359, 44743, '<td valign="top">Spectacular colors and lighting!  It''s fun to see a shot from *above* fireworks.</td>', 'Spectacular colors and lighting!  It''s fun to see a shot from *above* fireworks.', '2006-01-06 14:41:59.000000', NULL, 1),
(2010172, 276067, 50641, '<td valign="top">Hi. Nice crowd shot, well-conveyed.  Wonder how it would look with the contrast down one peg.  The sepia tones work well.  Thanks.</td>', 'Hi. Nice crowd shot, well-conveyed.  Wonder how it would look with the contrast down one peg.  The sepia tones work well.  Thanks.', '2006-01-06 14:42:38.000000', NULL, 1),
(2010176, 276316, 50780, '<td valign="top">Good subject matter - and good exposure! You brought out the essence of this person who survives working on the street.<br/>Gord</td>', 'Good subject matter - and good exposure! You brought out the essence of this person who survives working on the street.Gord', '2006-01-06 14:43:10.000000', NULL, 1),
(2010178, 274158, 44743, '<td valign="top">I guess this was going for the feel of motion, but it just seems to come across as blurred, esp since the motion appears to be vertical, instead of lateral.  Perhaps a shot of the outside moving past would have worked better?</td>', 'I guess this was going for the feel of motion, but it just seems to come across as blurred, esp since the motion appears to be vertical, instead of lateral.  Perhaps a shot of the outside moving past would have worked better?', '2006-01-06 14:44:05.000000', NULL, 1),
(2010181, 276360, 50641, '<td valign="top">I feel like they two gargantuan monoliths about to have a battle of the lights, haha.  Nice perspective and cropping/composition.</td>', 'I feel like they two gargantuan monoliths about to have a battle of the lights, haha.  Nice perspective and cropping/composition.', '2006-01-06 14:45:12.000000', NULL, 1),
(2010184, 276247, 50780, '<td valign="top">Good composition and exposure! It works wel for the subject matter. It almost looks like someone looking over a pair of binoculars.</td>', 'Good composition and exposure! It works wel for the subject matter. It almost looks like someone looking over a pair of binoculars.', '2006-01-06 14:46:31.000000', NULL, 1),
(2010185, 273455, 50641, '<td valign="top">He''s so hard to resist!  Nice depth and level of contrast.</td>', 'He''s so hard to resist!  Nice depth and level of contrast.', '2006-01-06 14:46:31.000000', NULL, 1),
(2010189, 275638, 50641, '<td valign="top">Pepto-bismol!  Nice catch, nice irony.</td>', 'Pepto-bismol!  Nice catch, nice irony.', '2006-01-06 14:48:03.000000', NULL, 1),
(2010190, 274978, 50780, '<td valign="top">I like your composition and your perspective. You have captured the essence of a city from a nautical point of view.<br/>Gord</td>', 'I like your composition and your perspective. You have captured the essence of a city from a nautical point of view.Gord', '2006-01-06 14:48:08.000000', NULL, 1),
(2010202, 274083, 50780, '<td valign="top">Good capturing of an event that certainly occurs in a city on a fairly regular basis. Good exposure for what could be a difficult situation.<br/>Gord</td>', 'Good capturing of an event that certainly occurs in a city on a fairly regular basis. Good exposure for what could be a difficult situation.Gord', '2006-01-06 14:50:56.000000', NULL, 1),
(2010207, 275767, 44743, '<td valign="top">Wow!  Great composition.  Nice lighting.  One of my favorites.</td>', 'Wow!  Great composition.  Nice lighting.  One of my favorites.', '2006-01-06 14:52:43.000000', NULL, 1),
(2010208, 275972, 50780, '<td valign="top">Toronto is where I was born and continue to work and live in. This certainly captures what the city is all about, but isn''t all that interesting to me as a photo.<br/>Gord</td>', 'Toronto is where I was born and continue to work and live in. This certainly captures what the city is all about, but isn''t all that interesting to me as a photo.Gord', '2006-01-06 14:52:57.000000', NULL, 1),
(2010211, 276438, 50780, '<td valign="top">I love this shot! I like your use of colour to tie rural and urban areas together.<br/>Gord</td>', 'I love this shot! I like your use of colour to tie rural and urban areas together.Gord', '2006-01-06 14:55:15.000000', NULL, 1),
(2010215, 275767, 50780, '<td valign="top">Cool use of light, colour, and movement in time to show off the city.<br/>Gord</td>', 'Cool use of light, colour, and movement in time to show off the city.Gord', '2006-01-06 14:56:58.000000', NULL, 1),
(2010221, 276211, 50641, '<td valign="top">Great shot and choice of perspective. A scene you can''t brush past. Possibly crop a bit of sky(?) - not sure.  Love those colors on the washline. I''d be interested in seeing other shots of this scene. Nice work.  Thanks.</td>', 'Great shot and choice of perspective. A scene you can''t brush past. Possibly crop a bit of sky(?) - not sure.  Love those colors on the washline. I''d be interested in seeing other shots of this scene. Nice work.  Thanks.', '2006-01-06 14:58:24.000000', NULL, 1),
(2010225, 276389, 50780, '<td valign="top">Not a bad night shot of a city.</td>', 'Not a bad night shot of a city.', '2006-01-06 14:59:14.000000', NULL, 1),
(2010226, 275215, 50641, '<td valign="top">I love the dizzying effect you''ve created.</td>', 'I love the dizzying effect you''ve created.', '2006-01-06 14:59:17.000000', NULL, 1),
(2010232, 275318, 50780, '<td valign="top">Good exposure, but the lady looks way too stiff and out of place - disassociated with the room.</td>', 'Good exposure, but the lady looks way too stiff and out of place - disassociated with the room.', '2006-01-06 15:01:19.000000', NULL, 1),
(2010233, 276466, 50641, '<td valign="top">My favorite.  Wouldn''t change a pixel.  All I can say is kudos.</td>', 'My favorite.  Wouldn''t change a pixel.  All I can say is kudos.', '2006-01-06 15:01:31.000000', NULL, 1),
(2010237, 274393, 50780, '<td valign="top">Love the use of light and reflections.</td>', 'Love the use of light and reflections.', '2006-01-06 15:02:30.000000', NULL, 1),
(2010238, 275846, 45776, '<td valign="top">Good job getting the snow exposed correctly. I still can''t do it.</td>', 'Good job getting the snow exposed correctly. I still can''t do it.', '2006-01-06 15:03:26.000000', NULL, 1),
(2010240, 275215, 45776, '<td valign="top">Excellent use of wide angle. The only thing I''d like to see on this image is a bit more contrast on the wheel, it doesn''t ''pop'' enough.</td>', 'Excellent use of wide angle. The only thing I''d like to see on this image is a bit more contrast on the wheel, it doesn''t ''pop'' enough.', '2006-01-06 15:03:30.000000', NULL, 1),
(2010243, 276247, 45776, '<td valign="top">Good shot, though it seems to have been shot or cropped unevenly.</td>', 'Good shot, though it seems to have been shot or cropped unevenly.', '2006-01-06 15:03:59.000000', NULL, 1),
(2010245, 276348, 50780, '<td valign="top">Good composition and interesting subject and view. However I would have made the image a little brighter.</td>', 'Good composition and interesting subject and view. However I would have made the image a little brighter.', '2006-01-06 15:04:25.000000', NULL, 1),
(2010247, 276438, 45776, '<td valign="top">I love the contrast here, it''s shame there isn''t much you can do about that haze in basic editing.</td>', 'I love the contrast here, it''s shame there isn''t much you can do about that haze in basic editing.', '2006-01-06 15:04:31.000000', NULL, 1),
(2010249, 276362, 45776, '<td valign="top">Great shot, I love the very tight composition.</td>', 'Great shot, I love the very tight composition.', '2006-01-06 15:05:06.000000', NULL, 1),
(2010255, 276140, 45776, '<td valign="top">Good composition, but a bit grainy and low detail. Was this taken with a long focal length zoom?</td>', 'Good composition, but a bit grainy and low detail. Was this taken with a long focal length zoom?', '2006-01-06 15:06:15.000000', NULL, 1),
(2010259, 276448, 46223, '<td valign="top">This is city life as i understand the subject. <br/>Overall composition is good. Too contrast for me</td>', 'This is city life as i understand the subject. Overall composition is good. Too contrast for me', '2006-01-06 15:07:08.000000', NULL, 1),
(2010260, 276267, 45776, '<td valign="top">Excellent shot.</td>', 'Excellent shot.', '2006-01-06 15:07:35.000000', NULL, 1),
(2010261, 276063, 45790, '<td valign="top">Striking photo.</td>', 'Striking photo.', '2006-01-06 15:07:47.000000', NULL, 1),
(2010262, 276099, 50780, '<td valign="top">Christmas in the city is certainly captured here</td>', 'Christmas in the city is certainly captured here', '2006-01-06 15:07:54.000000', NULL, 1),
