(2010276, 276363, 45776, '<td valign="top">This is a good shot, but the flash light in the front is really painful  for me.</td>', 'This is a good shot, but the flash light in the front is really painful  for me.', '2006-01-06 15:11:01.000000', NULL, 1),
(2010277, 273839, 50780, '<td valign="top">Shaddy side of town. Good exposure under the circumstances.</td>', 'Shaddy side of town. Good exposure under the circumstances.', '2006-01-06 15:11:07.000000', NULL, 1),
(2010278, 275645, 50780, '<td valign="top">You''ve captured the moment!</td>', 'You''ve captured the moment!', '2006-01-06 15:11:55.000000', NULL, 1),
