INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2010692, 274978, 41411, '<td valign="top">Where''s the life?<br/>Besides that, the shot leaves something to be desired - it''s a touch bland, though I like the way it''s composed. Perhaps more contrast, or do something with the colors?</td>', 'Where''s the life?Besides that, the shot leaves something to be desired - it''s a touch bland, though I like the way it''s composed. Perhaps more contrast, or do something with the colors?', '2006-01-06 17:50:50.000000', NULL, 1),
(2010694, 274721, 48467, '<td valign="top">old gag, shot too similar in style to numerous others in this contest to be an interesting or unique take on ''city life.''</td>', 'old gag, shot too similar in style to numerous others in this contest to be an interesting or unique take on ''city life.''', '2006-01-06 17:52:09.000000', NULL, 1),
(2010695, 274160, 41411, '<td valign="top">It''s a fabulous image, lot''s happenin'' and I like the red. However, I dislike your title, I don''t find it to be clever. Seven</td>', 'It''s a fabulous image, lot''s happenin'' and I like the red. However, I dislike your title, I don''t find it to be clever. Seven', '2006-01-06 17:52:36.000000', NULL, 1),
(2010697, 276211, 25553, '<td valign="top">you might be getting low scores from some people, but the reality is that this is ''city life'' for some people.  although the composition doesnt do much for me i like the realism presented here...</td>', 'you might be getting low scores from some people, but the reality is that this is ''city life'' for some people.  although the composition doesnt do much for me i like the realism presented here...', '2006-01-06 17:52:39.000000', NULL, 1),
(2010699, 276316, 48467, '<td valign="top">oh boy, another kinda grungy looking guy. is this really all there is to city life?</td>', 'oh boy, another kinda grungy looking guy. is this really all there is to city life?', '2006-01-06 17:53:45.000000', NULL, 1),
(2010702, 275261, 25553, '<td valign="top">this has nice colors but it is lacking a subject.. the viewer is not attracted to nothing in particular..</td>', 'this has nice colors but it is lacking a subject.. the viewer is not attracted to nothing in particular..', '2006-01-06 17:54:14.000000', NULL, 1),
(2010704, 274083, 48467, '<td valign="top">it looks like that truck is driving into hell</td>', 'it looks like that truck is driving into hell', '2006-01-06 17:54:29.000000', NULL, 1),
(2010705, 276108, 41411, '<td valign="top">I don''t like your title very much, and it''s difficult to see the "life." you can''t see what''s going on, i think perhaps you should''ve concentrated on the butcher shop, because the awning in front of it looks very photogenic</td>', 'I don''t like your title very much, and it''s difficult to see the "life." you can''t see what''s going on, i think perhaps you should''ve concentrated on the butcher shop, because the awning in front of it looks very photogenic', '2006-01-06 17:54:38.000000', NULL, 1),
(2010707, 276427, 41411, '<td valign="top">There''s no life in this picture, and it looks fairly rural. It''s a nice image but it doesn''t work for this challenge</td>', 'There''s no life in this picture, and it looks fairly rural. It''s a nice image but it doesn''t work for this challenge', '2006-01-06 17:55:28.000000', NULL, 1),
(2010709, 276267, 44490, '<td valign="top">This is one of the most interesting photos for this challenge, with the layers and types of transportation.  Maybe a little more contrast would help?  Love it.</td>', 'This is one of the most interesting photos for this challenge, with the layers and types of transportation.  Maybe a little more contrast would help?  Love it.', '2006-01-06 17:55:43.000000', NULL, 1),
(2010710, 275933, 44490, '<td valign="top">Interesting composition, colors, subject, flowing water, emotive.  Wish for just a touch more sharpness and less-blown white lights, but the major elements pull me in nicely.</td>', 'Interesting composition, colors, subject, flowing water, emotive.  Wish for just a touch more sharpness and less-blown white lights, but the major elements pull me in nicely.', '2006-01-06 17:55:49.000000', NULL, 1),
(2010711, 275939, 44490, '<td valign="top">Lovely lights and interesting mix of sharp and blurred skaters, nice composition, DOF, and sharpness.  Love it.</td>', 'Lovely lights and interesting mix of sharp and blurred skaters, nice composition, DOF, and sharpness.  Love it.', '2006-01-06 17:55:52.000000', NULL, 1),
(2010712, 275742, 41411, '<td valign="top">I don''t understand the title. The image is nice though... very photojournalistic</td>', 'I don''t understand the title. The image is nice though... very photojournalistic', '2006-01-06 17:56:03.000000', NULL, 1),
(2010713, 276058, 44490, '<td valign="top">Beautiful fireworks, building, lights, and composition, with hints of people.  Could hardly be better, and I like it a lot.</td>', 'Beautiful fireworks, building, lights, and composition, with hints of people.  Could hardly be better, and I like it a lot.', '2006-01-06 17:56:11.000000', NULL, 1),
(2010717, 276418, 41411, '<td valign="top">I am not laughing</td>', 'I am not laughing', '2006-01-06 17:56:18.000000', NULL, 1),
(2010718, 275215, 44490, '<td valign="top">Great use of fisheye.  Slight brighter levels and/or saturation might be better?  Curved horizon and clouds makes the sky seem like a huge moon - very nice.</td>', 'Great use of fisheye.  Slight brighter levels and/or saturation might be better?  Curved horizon and clouds makes the sky seem like a huge moon - very nice.', '2006-01-06 17:56:20.000000', NULL, 1),
(2010719, 275767, 44490, '<td valign="top">Beautiful lights, sharpness, and composition.  Slight angle for bridge might be better, but probably difficult to impossible, as a guess.  Nicely done.</td>', 'Beautiful lights, sharpness, and composition.  Slight angle for bridge might be better, but probably difficult to impossible, as a guess.  Nicely done.', '2006-01-06 17:56:26.000000', NULL, 1),
(2010720, 273957, 25553, '<td valign="top">the viewer is not attracted to anything in this picture. maybe a different angle can backlight the window and make it pop out of the darkness..</td>', 'the viewer is not attracted to anything in this picture. maybe a different angle can backlight the window and make it pop out of the darkness..', '2006-01-06 17:56:35.000000', NULL, 1),
(2010724, 275316, 48467, '<td valign="top">whoa yeah a traffic copter shot. a shot of a generic street in the middle of the day is not interesting, sorry.</td>', 'whoa yeah a traffic copter shot. a shot of a generic street in the middle of the day is not interesting, sorry.', '2006-01-06 17:57:33.000000', NULL, 1),
