INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2021230, 276211, 45857, '<td valign="top">I saw this place when I was in Honduras, no running water, two goats and a 2m satellite dish. Universal priorities.</td>', 'I saw this place when I was in Honduras, no running water, two goats and a 2m satellite dish. Universal priorities.', '2006-01-10 05:01:55.000000', NULL, 1),
(2021231, 274853, 45857, '<td valign="top">Great urban sense, but the desat purple hue really troubles me.</td>', 'Great urban sense, but the desat purple hue really troubles me.', '2006-01-10 05:04:08.000000', NULL, 1),
(2021233, 275359, 39181, '<td valign="top">impressive capture, take it this was taken from a hotel room half way up a mountain?</td>', 'impressive capture, take it this was taken from a hotel room half way up a mountain?', '2006-01-10 05:09:10.000000', NULL, 1),
(2021274, 275318, 33535, '<td valign="top">nice use of rule of thirds<br/>could be more authentic if the person was really working<br/>good job</td>', 'nice use of rule of thirdscould be more authentic if the person was really workinggood job', '2006-01-10 06:14:17.000000', NULL, 1),
(2021304, 276247, 47169, '<td valign="top">a brilliant viewpoint captured expertly. i love the deep color of the sky and the perspective in the buildings- you get e really good sence of scale with this picture. well done</td>', 'a brilliant viewpoint captured expertly. i love the deep color of the sky and the perspective in the buildings- you get e really good sence of scale with this picture. well done', '2006-01-10 06:37:51.000000', NULL, 1),
(2021308, 274721, 47169, '<td valign="top">the image is quite dark but i think the goes well with the surroundings. you have certainly captured this scene very well, especially the expression in the mans eyes. i think it conveys a sence of solitude in a city full of people- i really like this image, it makes me think. well done</td>', 'the image is quite dark but i think the goes well with the surroundings. you have certainly captured this scene very well, especially the expression in the mans eyes. i think it conveys a sence of solitude in a city full of people- i really like this image, it makes me think. well done', '2006-01-10 06:40:20.000000', NULL, 1),
(2021309, 275336, 47169, '<td valign="top">i like the grainy effect on this picture, its well captured and reflects city life well in my experience</td>', 'i like the grainy effect on this picture, its well captured and reflects city life well in my experience', '2006-01-10 06:42:21.000000', NULL, 1),
(2021311, 276067, 47169, '<td valign="top">a familiar scene to many! i really like the height this shot seems to be taken from- it gives perspective and clearly shows the sheer volume of people. well captured</td>', 'a familiar scene to many! i really like the height this shot seems to be taken from- it gives perspective and clearly shows the sheer volume of people. well captured', '2006-01-10 06:44:02.000000', NULL, 1),
(2021314, 275645, 47169, '<td valign="top">wow! i love the lighting in this shot, and i think you''ve done very well to achieve such minimal blur with the people- a problem i often have with night shots. nicely done</td>', 'wow! i love the lighting in this shot, and i think you''ve done very well to achieve such minimal blur with the people- a problem i often have with night shots. nicely done', '2006-01-10 06:46:12.000000', NULL, 1),
(2021316, 276098, 47169, '<td valign="top">its very different, and i really like that. the focus is extremely good and the reflection in the glasses is captured perfectly. you have a good range of color and great DOF. well done indeed</td>', 'its very different, and i really like that. the focus is extremely good and the reflection in the glasses is captured perfectly. you have a good range of color and great DOF. well done indeed', '2006-01-10 06:48:07.000000', NULL, 1),
(2021318, 274160, 47169, '<td valign="top">the title really adds to this shot. well done on a great capture and nice editing for the desaturation</td>', 'the title really adds to this shot. well done on a great capture and nice editing for the desaturation', '2006-01-10 06:49:21.000000', NULL, 1),
(2021319, 275939, 47169, '<td valign="top">the dark tones in this shot really bring out the brightness in the lights. you''ve captured a seasonal shot of city life very well. nice shot</td>', 'the dark tones in this shot really bring out the brightness in the lights. you''ve captured a seasonal shot of city life very well. nice shot', '2006-01-10 06:50:48.000000', NULL, 1),
(2021320, 274201, 47169, '<td valign="top">i like the idea, maybe roll your window down (i know it looks cold outside) to get rid of the reflections? otherwise, i like it- the vibrant colors and sence of movement are a great reflection of a city at night</td>', 'i like the idea, maybe roll your window down (i know it looks cold outside) to get rid of the reflections? otherwise, i like it- the vibrant colors and sence of movement are a great reflection of a city at night', '2006-01-10 06:52:49.000000', NULL, 1),
(2021349, 273455, 49973, '<td valign="top">Is that de Niro?  Someone who enjoys his job obviously.  The monochrome works well to draw you into the character</td>', 'Is that de Niro?  Someone who enjoys his job obviously.  The monochrome works well to draw you into the character', '2006-01-10 07:24:20.000000', NULL, 1),
