(2023113, 275099, 31859, '<td valign="top">Niagara Falls, right? Very nice.</td>', 'Niagara Falls, right? Very nice.', '2006-01-10 20:25:05.000000', NULL, 1),
(2023124, 275073, 31859, '<td valign="top">Love it! Not sure how it fits the City Life Challenge, but I still like the kitty!</td>', 'Love it! Not sure how it fits the City Life Challenge, but I still like the kitty!', '2006-01-10 20:28:36.000000', NULL, 1),
(2023126, 276316, 36981, '<td valign="top">What a wonderful image.  This is a great photograph!</td>', 'What a wonderful image.  This is a great photograph!', '2006-01-10 20:28:42.000000', NULL, 1),
(2023127, 275767, 36981, '<td valign="top">Beautiful composition &amp; tones!</td>', 'Beautiful composition & tones!', '2006-01-10 20:28:53.000000', NULL, 1),
