(2023806, 274980, 50928, '<td valign="top">Love the effect of a slow shutter speed</td>', 'Love the effect of a slow shutter speed', '2006-01-10 23:23:26.000000', NULL, 1),
(2023808, 276116, 42984, '<td valign="top">I love street candid and this is one I love a lot!  The expressions, the action, the implied story ... very well done</td>', 'I love street candid and this is one I love a lot!  The expressions, the action, the implied story ... very well done', '2006-01-10 23:23:56.000000', NULL, 1),
